function toApiPost(value:Row){return {title:value.name,slug:value.slug||undefined,summary:value.summary,category:value.category,tags:value.tags,content:value.content,coverImageUrl:value.coverImageUrl||value.images?.[0]||null,images:value.images,status:value.status==="Đã xuất bản"?"PUBLISHED":value.status==="Đã lên lịch"?"SCHEDULED":"DRAFT",seoTitle:value.seoTitle,seoDescription:value.seoDescription};}
const menu:{key:ViewKey;label:string;icon:string;badge?:string;chevron?:boolean}[]=[{key:'overview',label:'Tổng quan',icon:'home'},{key:'orders',label:'Đơn hàng',icon:'bag',chevron:true},{key:'products',label:'Sản phẩm',icon:'box',chevron:true},{key:'customers',label:'Khách hàng',icon:'users'},{key:'promotions',label:'Khuyến mãi',icon:'tag',chevron:true},{key:'posts',label:'Bài viết / Blog',icon:'file',chevron:true},{key:'inventory',label:'Quản lý tồn kho',icon:'inventory',chevron:true},{key:'banners',label:'Banner & Footer',icon:'image'},{key:'reports',label:'Báo cáo',icon:'chart',chevron:true},{key:'settings',label:'Cài đặt',icon:'settings'}];
const viewMeta:Record<string,{title:string;description:string}>={overview:{title:'Tổng quan',description:'Tổng quan hoạt động của cửa hàng.'},orders:{title:'Đơn hàng',description:'Theo dõi và cập nhật trạng thái các đơn hàng.'},products:{title:'Sản phẩm',description:'Chỉ quản lý bài đăng trên website. SKU, biến thể và số lượng do mục Quản lý tồn kho phụ trách.'},materials:{title:'Loại đá',description:'Quản lý riêng loại đá cho trang sức và mặt đá quý.'},productCreate:{title:'Thêm bài đăng',description:'Chọn SKU đang có trong kho để tạo bài đăng bán trên GEME.'},categories:{title:'Danh mục',description:'Tổ chức sản phẩm theo nhóm để khách dễ tìm kiếm.'},customers:{title:'Khách hàng',description:'Thông tin khách hàng và lịch sử mua sắm.'},promotionCreate:{title:'Tạo khuyến mãi',description:'Lập chương trình khuyến mãi cho cửa hàng GEME.'},promotions:{title:'Khuyến mãi',description:'Quản lý mã ưu đãi đang áp dụng cho cửa hàng.'},posts:{title:'Bài viết / Blog',description:'Quản lý bài viết, chủ đề và trạng thái xuất bản.'},blogEditor:{title:'Trình soạn thảo blog',description:'Soạn bài viết cho GEME Journal.'},inventory:{title:'Quản lý tồn kho',description:'Theo dõi số lượng, nhập/xuất và lịch sử trong kho.'},reports:{title:'Báo cáo',description:'Tổng hợp hoạt động kinh doanh theo thời gian.'},revenue:{title:'Báo cáo theo doanh thu',description:'Theo dõi doanh thu và hiệu quả kinh doanh theo thời gian.'},settings:{title:'Cài đặt',description:'Cấu hình thông tin hiển thị cơ bản cho cửa hàng.'}};
viewMeta.banners={title:'Banner & Footer',description:'Quản lý hình ảnh banner, thông tin liên hệ và chân trang.'};
viewMeta.pricing={title:'Hồ sơ giá',description:'Quản lý bảng giá chuẩn theo SKU và biến thể; giá này được dùng trên website và đồng bộ sang POS365.'};
const money=(n:number|string)=>new Intl.NumberFormat('vi-VN').format(Number(n)||0)+' ₫';
function statusClass(value:string){return /Đã giao|Đang bán|Đang hoạt động|Đang hiển thị|Đã xuất bản|Thành viên|Hoàn tất|Còn hàng/i.test(value)?'green':/Chờ|Đang xử lý|Đang áp dụng|Bản nháp|Tạm ẩn|Sắp hết/i.test(value)?'amber':/Đang giao/i.test(value)?'blue':'red';}
function Pill({children}:{children:string}){return <span className={`status-pill ${statusClass(children)}`}>{children}</span>;}
function Thumb({index=0}:{index?:number}){const colors=['#9274a2','#aab9c2','#779b82','#c3a176','#a36561'];return <span className="product-thumb" style={{color:colors[index%colors.length]}}><Icon name="gem"/></span>;}
function PageTitle({view,children}:{view:ViewKey;children?:React.ReactNode}){return <div className="page-heading"><div><h1>{viewMeta[view].title}</h1><p>{viewMeta[view].description}</p></div>{children}</div>;}

const fieldDefs:Record<GeneralFormView,FieldDefinition[]>={products:[{key:'id',label:'Mã sản phẩm'},{key:'name',label:'Tên sản phẩm'},{key:'price',label:'Giá bán (₫)',numeric:true},{key:'status',label:'Trạng thái'}],categories:[{key:'name',label:'Tên danh mục'},{key:'slug',label:'Đường dẫn (slug)'},{key:'products',label:'Số sản phẩm',numeric:true},{key:'status',label:'Trạng thái'}],customers:[{key:'id',label:'Mã khách hàng'},{key:'name',label:'Họ tên'},{key:'phone',label:'Số điện thoại'},{key:'email',label:'Email',type:'email'},{key:'orders',label:'Số đơn hàng',numeric:true},{key:'total',label:'Tổng chi tiêu (₫)',numeric:true}],promotions:[{key:'code',label:'Mã ưu đãi'},{key:'name',label:'Tên chương trình'},{key:'discount',label:'Mức ưu đãi'},{key:'uses',label:'Lượt dùng',numeric:true},{key:'expiry',label:'Hạn sử dụng'}],posts:[{key:'name',label:'Tiêu đề bài viết'},{key:'category',label:'Danh mục'},{key:'date',label:'Ngày đăng'}]};

export default function AdminShell(){
  const [view,setView]=useState<ViewKey>('overview');
  const [data,setData]=useState<AdminData>(seed);
  const [siteSettings,setSiteSettings]=useState<Record<string,any>>({storeName:'GEME',supportEmail:'',phone:'',address:''});
  const [blogCategories,setBlogCategories]=useState<string[]>([]);
  const [blogPostDraft,setBlogPostDraft]=useState<Row|null>(null);
  const [apiStatus,setApiStatus]=useState<"connecting"|"connected"|"offline">("connecting");
  const [catalogSyncStatus,setCatalogSyncStatus]=useState<MaterialSyncStatus>('connecting');
  const [pos365Status,setPos365Status]=useState<Pos365Status|null>(null);
  const [pos365QueueSummary,setPos365QueueSummary]=useState<Pos365QueueSummary|null>(null);
  const [pos365Checking,setPos365Checking]=useState(false);
  const [pos365StockSyncing,setPos365StockSyncing]=useState(false);
  const [pos365Result,setPos365Result]=useState<Pos365TestResult|null>(null);
  const [search,setSearch]=useState('');
  const [tableSearch,setTableSearch]=useState('');
  const [menuOpen,setMenuOpen]=useState(false);
  const [expandedMenus,setExpandedMenus]=useState<Partial<Record<ViewKey,boolean>>>({});
  const [toast,setToast]=useState('');
  const [formView,setFormView]=useState<GeneralFormView|null>(null);
  const [editing,setEditing]=useState<Row|null>(null);
  const [draft,setDraft]=useState<Record<string,string>>({});
  const [selectedOrderId,setSelectedOrderId]=useState('');
  const [receiptOrderId,setReceiptOrderId]=useState('');
  const [selectedOrderRows,setSelectedOrderRows]=useState<string[]>([]);
  const [statusFilter,setStatusFilter]=useState('');
  const [paymentFilter,setPaymentFilter]=useState('');
  const [shippingFilter,setShippingFilter]=useState('');
  const [orderDateFrom,setOrderDateFrom]=useState('');
  const [orderDateTo,setOrderDateTo]=useState('');
  const [productCategoryPreset,setProductCategoryPreset]=useState<AdminCategory>();
  const [dashboardReport,setDashboardReport]=useState<DashboardReport|null>(null);
  const [dashboardReportStatus,setDashboardReportStatus]=useState<"loading"|"loaded"|"error">("loading");
  useEffect(()=>{
    let alive=true;
    const get=async(path:string)=>{const response=await fetch(`${apiBase}/${path}`,{cache:'no-store'});if(!response.ok)throw new Error(`GET ${path} failed (${response.status})`);return response.json();};
    void Promise.all([get('categories'),get('products?all=true'),get('orders'),get('customers'),get('promotions'),get('blog?all=true'),get('materials'),get('settings')]).then(([categories,products,orders,customers,promotions,posts,materials,settings])=>{
      if(!alive)return;
      const mappedOrders=(orders as Row[]).map(fromApiOrder);
      setData({categories:(categories as Row[]).map(fromApiCategory),products:(products as Row[]).filter((item)=>item.status!=="ARCHIVED").map(fromApiProduct),orders:mappedOrders,customers:(customers as Row[]).map(fromApiCustomer),promotions:(promotions as Row[]).map(fromApiPromotion),posts:(posts as Row[]).map(fromApiPost),materials:(materials as Row[]).map(fromApiMaterial)});
      setSelectedOrderId(current=>current||mappedOrders[0]?.id||'');
      setBlogCategories(Array.isArray((settings as Row).blogCategories)?(settings as Row).blogCategories.filter((item:unknown)=>typeof item==='string'):Array.from(new Set((posts as Row[]).map((post)=>String(post.category||'')).filter(Boolean))));
      setSiteSettings({storeName:String((settings as Row).storeName||'GEME'),supportEmail:String((settings as Row).supportEmail||''),phone:String((settings as Row).phone||''),address:String((settings as Row).address||'')});
      setApiStatus('connected');setCatalogSyncStatus('connected');
    }).catch(()=>{if(alive){setApiStatus('offline');setCatalogSyncStatus('offline');}});
    const events=new EventSource(`${apiBase}/materials/events`);
    events.onmessage=(event)=>{try{const records=JSON.parse(event.data) as Row[];if(alive)setData(old=>({...old,materials:records.map(fromApiMaterial)}));}catch{ /* ignore malformed server events */ }};
    return()=>{alive=false;events.close();};
  },[]);
  useEffect(()=>{
    let alive=true;
    void fetch(`${apiBase}/integrations/pos365/sync-summary`,{cache:'no-store'}).then(async response=>{
      if(!response.ok)throw new Error('Không đọc được trạng thái hàng đợi POS365.');
      return response.json() as Promise<Pos365QueueSummary>;
    }).then(summary=>{if(alive)setPos365QueueSummary(summary);}).catch(()=>{if(alive)setPos365QueueSummary(null);});
    return()=>{alive=false;};
  },[]);
  useEffect(()=>{
    let alive=true;
    void fetch(`${apiBase}/integrations/pos365/status`,{cache:'no-store'}).then(async response=>{
      if(!response.ok)throw new Error('Không đọc được trạng thái POS365.');
      return response.json() as Promise<Pos365Status>;
    }).then(status=>{if(alive)setPos365Status(status);}).catch(()=>{if(alive)setPos365Status(null);});
    return()=>{alive=false;};
  },[]);
  useEffect(()=>{if(!toast)return;const timer=window.setTimeout(()=>setToast(''),2600);return()=>window.clearTimeout(timer);},[toast]);
  const rows=useMemo<Row[]>(()=>(['products','orders','categories','customers','promotions','posts'].includes(view)?data[view as keyof AdminData] as Row[]:[]),[data,view]);
  const filteredRows=useMemo(()=>rows.filter(row=>Object.values(row).some(value=>String(value).toLocaleLowerCase('vi').includes(tableSearch.toLocaleLowerCase('vi'))||String(value).toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')))),[rows,tableSearch,search]);
  const orderRows=useMemo(()=>data.orders.filter(order=>{const orderDay=order.placedAt&&!Number.isNaN(new Date(order.placedAt).getTime())?new Date(order.placedAt).toISOString().slice(0,10):'';return (!statusFilter||order.status===statusFilter)&&(!paymentFilter||order.payment===paymentFilter)&&(!shippingFilter||order.shipping.toLowerCase().includes(shippingFilter.toLowerCase()))&&(!orderDateFrom||Boolean(orderDay&&orderDay>=orderDateFrom))&&(!orderDateTo||Boolean(orderDay&&orderDay<=orderDateTo))&&(!search||`${order.id} ${order.customer} ${order.phone} ${order.product} ${order.sku||''} ${(order.items||[]).map((item:OrderReceiptLine)=>item.productSku||'').join(' ')}`.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));}),[data.orders,statusFilter,paymentFilter,shippingFilter,orderDateFrom,orderDateTo,search]);
  const selectedOrder=data.orders.find(order=>order.id===selectedOrderId);
  const selectedReceiptOrder=data.orders.find(order=>order.id===receiptOrderId);
  const notify=(text:string)=>setToast(text);
  const testPos365Connection=async()=>{
    if(pos365Checking)return;
    setPos365Checking(true);setPos365Result(null);
    try{
      const response=await fetch(`${apiBase}/integrations/pos365/test-connection`,{method:'POST',cache:'no-store'});
      const result=await response.json() as Pos365TestResult;
      setPos365Result(result);
      if(!response.ok)throw new Error(result.message||`POS365 API trả về lỗi ${response.status}.`);
    }catch(error){
      setPos365Result({ok:false,code:'API_ERROR',message:error instanceof Error?error.message:'Không kiểm tra được kết nối POS365.'});
    }finally{setPos365Checking(false);}
  };
  const apiRequest=async(path:string,method='GET',body?:unknown)=>{const response=await fetch(`${apiBase}/${path}`,{method,headers:body===undefined?undefined:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok){let message=`API trả về lỗi ${response.status}.`;try{const detail=await response.json();message=Array.isArray(detail.message)?detail.message.join(' '):detail.message||message;}catch{}throw new Error(message);}return method==='DELETE'?null:response.json();};
  useEffect(()=>{
    if(!["overview","reports","revenue"].includes(view)||apiStatus!=="connected")return;
    let alive=true;
    setDashboardReportStatus("loading");
    void fetch(`${apiBase}/reports/overview`,{cache:"no-store"}).then(async(response)=>{
      if(!response.ok)throw new Error(`GET reports/overview failed (${response.status})`);
      return response.json() as Promise<DashboardReport>;
    }).then((report)=>{if(alive){setDashboardReport(report);setDashboardReportStatus("loaded");}}).catch(()=>{if(alive)setDashboardReportStatus("error");});
    return()=>{alive=false;};
  },[view,apiStatus]);
  useEffect(()=>{
    if(view!=='products'||apiStatus!=='connected')return;
    let alive=true;
    void fetch(`${apiBase}/products?all=true`,{cache:'no-store'}).then(async(response)=>{if(!response.ok)throw new Error(`GET products failed (${response.status})`);return response.json() as Promise<Row[]>;}).then((records)=>{if(alive)setData(old=>({...old,products:records.filter((item)=>item.status!=="ARCHIVED").map(fromApiProduct)}));}).catch((error)=>{if(alive)notify(error instanceof Error?error.message:'Không thể làm mới danh sách sản phẩm.');});
    return()=>{alive=false;};
  },[view,apiStatus]);
  useEffect(()=>{
    let alive=true;
    let refreshTimer:number|undefined;
    const events=new EventSource(`${apiBase}/products/events`);
    events.onmessage=(event)=>{
      let change:Row;
      try{change=JSON.parse(event.data) as Row;}catch{return;}
      if(change.entity!=="product")return;
      if(refreshTimer)window.clearTimeout(refreshTimer);
      refreshTimer=window.setTimeout(()=>{
        void fetch(`${apiBase}/products?all=true`,{cache:"no-store"}).then(async(response)=>{
          if(!response.ok)throw new Error(`GET products failed (${response.status})`);
          return response.json() as Promise<Row[]>;
        }).then((records)=>{if(alive)setData(old=>({...old,products:records.filter((item)=>item.status!=="ARCHIVED").map(fromApiProduct)}));}).catch(()=>{});
      },120);
    };
    return()=>{alive=false;events.close();if(refreshTimer)window.clearTimeout(refreshTimer);};
  },[]);
  const openBlogEditor=(post?:Row)=>{setBlogPostDraft(post?{...post}:null);setView('blogEditor');setMenuOpen(false);window.scrollTo({top:0,behavior:'smooth'});};
  const saveBlogCategory=async(name:string)=>{const normalized=name.trim();const existing=blogCategories.find((category)=>category.toLocaleLowerCase('vi')===normalized.toLocaleLowerCase('vi'));if(existing)return blogCategories;const next=[...blogCategories,normalized];await apiRequest('settings','PATCH',{blogCategories:next});setBlogCategories(next);return next;};
  const saveBlogPost=async(post:Row)=>{const id=post.apiId?encodeURIComponent(String(post.apiId)):'';const saved=await apiRequest(`blog${id?`/${id}`:''}`,id?'PATCH':'POST',toApiPost(post)) as Row;const mapped=fromApiPost(saved);setData(old=>({...old,posts:id?old.posts.map(item=>item.apiId===mapped.apiId?mapped:item):[mapped,...old.posts]}));setView('posts');setBlogPostDraft(null);setMenuOpen(false);window.scrollTo({top:0,behavior:'smooth'});notify(mapped.status==='Đã xuất bản'?'Bài viết đã xuất bản và lưu vào database.':'Bản nháp đã lưu vào database.');};
  const persistCollection=async(kind:'categories'|'promotions'|'posts',current:Row[],next:Row[])=>{
    const route=kind==='posts'?'blog':kind;
    const normalize=(rows:Row[])=>kind==='categories'?rows.map(fromApiCategory):kind==='promotions'?rows.map(fromApiPromotion):rows.map(fromApiPost);
    const encode=(row:Row)=>kind==='categories'?toApiCategory(row as AdminCategory):kind==='promotions'?toApiPromotion(row):toApiPost(row);
    const keyOf=(row:Row)=>String(row.apiId||row.id||row.code||row.slug||row.name);
    const oldById=new Map(current.filter(row=>row.apiId||row.id).map(row=>[keyOf(row),row]));
    const nextIds=new Set(next.filter(row=>row.apiId||row.id).map(keyOf));
    for(const old of current){if((old.apiId||old.id)&&!nextIds.has(keyOf(old))){if(kind!=='categories')await apiRequest(`${route}/${encodeURIComponent(String(old.apiId||old.id))}`,'DELETE');}}
    for(const row of next){
      const old=row.apiId||row.id?oldById.get(keyOf(row)):undefined;
      if(!old){const saved=await apiRequest(route,'POST',encode(row));if(kind==='categories')row.apiId=String(saved.id);}
      else {const before=JSON.stringify(encode(old));const after=JSON.stringify(encode(row));if(before!==after)await apiRequest(`${route}/${encodeURIComponent(String(old.apiId||old.id))}`,'PATCH',encode(row));}
    }
    const remote=await apiRequest(kind==='categories'?route:kind==='promotions'?route:'blog?all=true') as Row[];
    const mapped=normalize(remote);
    setData(old=>({...old,[kind]:mapped}));
    return mapped;
  };
  const persistProduct=async(product:Product,publish?:boolean)=>{
    const uploadImage=async(value:string|undefined,filename:string):Promise<string>=>{
      if(!value?.startsWith('data:image/'))return value||'';
      const comma=value.indexOf(',');
      if(comma<0)throw new Error('Dữ liệu ảnh sản phẩm không hợp lệ.');
      const mimeType=value.slice(5,value.indexOf(';'));
      const asset=await apiRequest('media','POST',{filename,mimeType,base64:value.slice(comma+1),alt:product.name}) as Row;
      if(typeof asset.url!=='string'||!asset.url)throw new Error('Không nhận được đường dẫn ảnh đã lưu trong database.');
      return asset.url;
    };
    const sourceGallery=product.gallery?.length?product.gallery:product.image?[product.image]:[];
    const gallery=await Promise.all(sourceGallery.slice(0,10).map((image,index)=>uploadImage(image,`product-${product.id}-${index+1}.webp`)));
    const technicalImage=await uploadImage(product.technicalImage,`product-${product.id}-technical.webp`);
    const priceVariants=await Promise.all((product.priceVariants||[]).map(async(variant,index)=>({
      ...variant,
      imageUrls:await Promise.all((variant.imageUrls||[]).slice(0,8).map((image,imageIndex)=>uploadImage(image,`variant-${product.id}-${index+1}-${imageIndex+1}.webp`))),
    })));
    const productWithMedia={...product,gallery,image:gallery[0]||'',technicalImage,priceVariants};
    const saved=await apiRequest(`products${product.apiId?`/${encodeURIComponent(product.apiId)}`:''}`,product.apiId?'PATCH':'POST',toApiProduct(productWithMedia,publish)) as Row;
    const mapped=fromApiProduct(saved);
    setData(old=>({...old,products:mapped.status==="Đã gỡ bài"?old.products.filter(item=>item.apiId!==mapped.apiId):[mapped,...old.products.filter(item=>item.apiId!==mapped.apiId)]}));
    return mapped;
  };
  const deleteProduct=async(product:Product)=>{
    if(!product.apiId)throw new Error('Không tìm thấy mã sản phẩm trong API.');
    await apiRequest(`products/${encodeURIComponent(product.apiId)}`,'DELETE');
    setData(old=>({...old,products:old.products.filter(item=>item.apiId!==product.apiId)}));
  };
  const reloadProducts=async()=>{const records=await apiRequest('products?all=true') as Row[];setData(old=>({...old,products:records.filter(item=>item.status!=='ARCHIVED').map(fromApiProduct)}));};
  const syncAllPrices=async()=>await apiRequest('integrations/pos365/sync-product-prices','POST',{}) as {queued?:number;skippedWithoutPrice?:number};
  const syncUnsentOrders=async()=>await apiRequest('integrations/pos365/sync-unsent-orders','POST',{}) as {queued?:number};
  const syncCurrentInventory=async()=>{
    if(pos365StockSyncing)return;
    setPos365StockSyncing(true);
    try{
      const result=await apiRequest('integrations/pos365/sync-current-inventory','POST',{}) as {stockLines?:number;verified?:number;targetUnits?:number;createdProducts?:number};
      notify(result.stockLines?`Đã đồng bộ và xác minh ${result.verified??0}/${result.stockLines} SKU, tổng ${result.targetUnits??0} sản phẩm tồn.`:'Kho GEME hiện chưa có SKU để đồng bộ.');
    }catch(error){notify(error instanceof Error?error.message:'Không thể đồng bộ tồn hiện tại sang POS365.');}
    finally{setPos365StockSyncing(false);}
  };
  const commitCollection=(kind:'categories'|'promotions'|'posts',next:Row[])=>{void persistCollection(kind,data[kind] as Row[],next).catch(error=>notify(error instanceof Error?error.message:'Không thể đồng bộ dữ liệu với API.'));};
  const deleteCategory=async(id:string):Promise<AdminCategory[]>=>{
    await apiRequest(`categories/${encodeURIComponent(id)}`,'DELETE');
    const [categories,products]=await Promise.all([apiRequest('categories'),apiRequest('products?all=true')]) as [Row[],Row[]];
    const mappedCategories=categories.map(fromApiCategory);
    const mappedProducts=products.filter((item)=>item.status!=="ARCHIVED").map(fromApiProduct);
    setData(old=>({...old,categories:mappedCategories,products:mappedProducts}));
    return mappedCategories;
  };
  const persistMaterial=async(method:'POST'|'PATCH'|'DELETE',id?:string,value:MaterialMutationValue={}):Promise<MaterialOption|null>=>{
    if(catalogSyncStatus!=='connected')throw new Error('API chưa kết nối. Hãy khởi động backend rồi thử lại.');
    const url=`${materialsApiBase}/materials${id?`/${encodeURIComponent(id)}`:''}`;
    const payload:Row={};
    if(value.name!==undefined)payload.name=value.name;
    if(value.scope!==undefined)payload.scope=value.scope==='Đá quý'?'GEMSTONE':'JEWELRY';
    if(value.kind!==undefined)payload.kind=value.kind;
    if(value.active!==undefined)payload.active=value.active;
    if(value.imageUrl!==undefined)payload.imageUrl=value.imageUrl;
    if(value.sortOrder!==undefined)payload.sortOrder=value.sortOrder;
    const response=await fetch(url,{method,headers:method==='DELETE'?undefined:{'Content-Type':'application/json'},body:method==='DELETE'?undefined:JSON.stringify(method==='POST'?toApiMaterial(value):payload)});
    if(!response.ok){if(method==='DELETE'&&response.status===404)return null;let message='Không thể lưu thay đổi vào database.';try{const detail=await response.json();if(typeof detail.message==='string')message=detail.message;else if(Array.isArray(detail.message))message=detail.message.join(' ');}catch{}throw new Error(message);}
    if(method==='DELETE')return null;
    return fromApiMaterial(await response.json() as Row);
  };
  const go=(key:ViewKey)=>{setView(key);setSearch('');setTableSearch('');setMenuOpen(false);window.scrollTo({top:0,behavior:'smooth'});};
  const requestProductCreate=(initialCategory?:AdminCategory)=>{setProductCategoryPreset(initialCategory);setView('productCreate');setSearch('');setTableSearch('');setMenuOpen(false);window.scrollTo({top:0,behavior:'smooth'});};
  const openProductCreate=()=>requestProductCreate();
  const backFromProductCreate=()=>{setProductCategoryPreset(undefined);go('products');};
  const openForm=(kind:keyof typeof fieldDefs,item?:Row)=>{setFormView(kind);setEditing(item||null);const initial:Record<string,string>={};fieldDefs[kind].forEach(field=>{initial[field.key]=item?String(item[field.key]??''):'';});if(!item&&kind==='customers'){initial.id=`KH${String(Date.now()).slice(-4)}`;initial.status='Active';initial.orders='0';initial.total='0';}if(!item&&kind==='products')initial.id=`SP${String(Date.now()).slice(-4)}`;if(!item&&kind==='posts')initial.date=new Date().toLocaleDateString('vi-VN');setDraft(initial);};
  const closeForm=()=>{setFormView(null);setEditing(null);setDraft({});};
  const saveForm=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!formView)return;const entry:Row={...draft};void apiRequest(`customers${editing?.apiId?`/${editing.apiId}`:''}`,editing?.apiId?'PATCH':'POST',{name:entry.name,email:entry.email||null,phone:entry.phone||null,status:entry.status==='Inactive'?'INACTIVE':'ACTIVE',defaultAddress:entry.address||null,note:entry.note||null,segment:entry.segment||'Khách mới'}).then((saved)=>{const mapped=fromApiCustomer(saved as Row);setData(old=>({...old,customers:editing?.apiId?old.customers.map(row=>row.apiId===editing.apiId?mapped:row):[mapped,...old.customers]}));notify(editing?'Đã cập nhật khách hàng.':'Đã thêm khách hàng.');closeForm();}).catch(error=>notify(error instanceof Error?error.message:'Không thể lưu khách hàng vào API.'));};
  const changeOrder=(id:string,status:string)=>{const row=data.orders.find(order=>order.id===id);if(!row?.apiId){notify('Không tìm thấy mã đơn hàng trong API.');return;}const statuses:Record<string,string>={'Chờ xác nhận':'PENDING_CONFIRMATION','Đang xử lý':'PROCESSING','Đang giao':'SHIPPING','Đã giao':'DELIVERED','Đã hủy':'CANCELLED'};void apiRequest(`orders/${row.apiId}/status`,'PATCH',{status:statuses[status]}).then(saved=>{const mapped=fromApiOrder(saved as Row);setData(old=>({...old,orders:old.orders.map(order=>order.apiId===row.apiId?mapped:order)}));notify(`Đã cập nhật đơn hàng ${id}.`);}).catch(error=>notify(error instanceof Error?error.message:'Không thể cập nhật trạng thái đơn hàng.'));};
   const createPosCustomer=async(customer:{name:string;phone:string})=>{const saved=await apiRequest('customers','POST',{name:customer.name,phone:customer.phone,email:null,status:'ACTIVE',segment:'Khách mới'});const mapped=fromApiCustomer(saved as Row);setData(old=>({...old,customers:[mapped,...old.customers.filter(row=>row.apiId!==mapped.apiId)]}));return mapped;};
   const createPosOrder=async(order:Record<string,unknown>)=>{const saved=await apiRequest('orders','POST',order) as Row;const mapped=fromApiOrder(saved);setData(old=>({...old,orders:[mapped,...old.orders.filter(row=>row.apiId!==mapped.apiId)]}));setSelectedOrderId(mapped.id);setView('orders');setMenuOpen(false);notify(saved.payments?.[0]?.status==='PAID'?`Đã hoàn tất đơn ${mapped.id} và cập nhật tồn kho.`:`Đã lưu đơn ${mapped.id} chờ thanh toán.`);void Promise.all([apiRequest('products?all=true'),apiRequest('customers'),apiRequest('orders')]).then(([products,customers,orders])=>setData(old=>({...old,products:(products as Row[]).filter(item=>item.status!=='ARCHIVED').map(fromApiProduct),customers:(customers as Row[]).map(fromApiCustomer),orders:(orders as Row[]).map(fromApiOrder)}))).catch(()=>{});};
   const togglePost=(name:string)=>{setData(old=>({...old,posts:old.posts.map(post=>post.name===name?{...post,status:post.status==='Đã xuất bản'?'Bản nháp':'Đã xuất bản'}:post)}));};
  const exportOrders=()=>{const fields=['Mã đơn','Khách hàng','Sản phẩm','Tổng tiền','Thanh toán','Trạng thái','Ngày'];const csv=[fields.join(','),...orderRows.map(order=>[order.id,order.customer,order.product,order.total,order.payment,order.status,order.date].map(value=>`"${String(value).replaceAll('"','""')}"`).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='geme-don-hang.csv';link.click();URL.revokeObjectURL(url);};

  const renderOrders=(items:Row[],mini=false)=><div className="page-table-wrap"><table className="orders-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Tổng tiền</th><th>Trạng thái</th><th>Thời gian</th>{!mini&&<th></th>}</tr></thead><tbody>{items.length?items.map((row,index)=><tr key={String(row.id)}><td className="order-id">{String(row.id)}</td><td>{String(row.customer)}</td><td className="amount">{money(row.total as number)}</td><td>{mini?<Pill>{String(row.status)}</Pill>:<select className="table-status" value={String(row.status)} onChange={e=>changeOrder(String(row.id),e.target.value)}><option>Chờ xác nhận</option><option>Đang xử lý</option><option>Đang giao</option><option>Đã giao</option><option>Đã hủy</option></select>}</td><td>{String(row.time)}</td>{!mini&&<td><button className="row-action" onClick={()=>notify('Chi tiết đơn hàng sẽ hiển thị khi kết nối backend.')}>Chi tiết</button></td>}</tr>):<tr><td className="table-empty" colSpan={6}>Không có dữ liệu phù hợp.</td></tr>}</tbody></table></div>;
  const renderGeneralRows=()=>{
    if(!filteredRows.length)return <tr><td className="table-empty" colSpan={8}>Không có dữ liệu phù hợp.</td></tr>;
    return filteredRows.map((row,index)=>{
      if(view==='products')return <tr key={String(row.id)}><td className="strong-cell">{String(row.id)}</td><td><span className="product-cell">{<Thumb index={index}/>}<span>{String(row.name)}</span></span></td><td>{money(row.price as number)}</td><td>{row.sold}</td><td>{row.stock}</td><td><Pill>{String(row.status)}</Pill></td><td><button className="row-action" onClick={()=>openForm('products',row)}>Sửa</button></td></tr>;
      
      if(view==='categories')return <tr key={String(row.slug)}><td className="strong-cell">{String(row.name)}</td><td>{String(row.slug)}</td><td>{row.products} sản phẩm</td><td><Pill>{String(row.status)}</Pill></td><td><button className="row-action" onClick={()=>openForm('categories',row)}>Sửa</button></td></tr>;
      if(view==='customers')return <tr key={String(row.id)}><td className="strong-cell">{String(row.id)}</td><td>{String(row.name)}</td><td>{String(row.email)}</td><td>{row.orders}</td><td>{money(row.total as number)}</td><td><Pill>{String(row.status)}</Pill></td><td><button className="row-action" onClick={()=>notify('Hồ sơ chi tiết sẽ được tải từ API sau này.')}>Chi tiết</button></td></tr>;
      if(view==='promotions')return <tr key={String(row.code)}><td className="strong-cell">{String(row.code)}</td><td>{String(row.name)}</td><td>{String(row.discount)}</td><td>{row.uses}</td><td>{String(row.expiry)}</td><td><Pill>{String(row.status)}</Pill></td><td><button className="row-action" onClick={()=>openForm('promotions',row)}>Sửa</button></td></tr>;
      return <tr key={String(row.name)}><td className="strong-cell">{String(row.name)}</td><td>{String(row.category)}</td><td>{String(row.date)}</td><td><button className="row-action" onClick={()=>togglePost(String(row.name))}><Pill>{String(row.status)}</Pill></button></td><td><button className="row-action" onClick={()=>openForm('posts',row)}>Sửa</button></td></tr>;
    });
  };
  const headers:Record<string,string[]>={products:['Mã SP','Sản phẩm','Giá bán','Đã bán','Tồn kho','Trạng thái',''],categories:['Tên danh mục','Đường dẫn','Sản phẩm','Trạng thái',''],customers:['Mã KH','Khách hàng','Email','Đơn hàng','Tổng chi tiêu','Hạng',''],promotions:['Mã ưu đãi','Tên chương trình','Ưu đãi','Lượt dùng','Hạn sử dụng','Trạng thái',''],posts:['Tiêu đề bài viết','Danh mục','Ngày đăng','Trạng thái','']};
  const addLabel:Partial<Record<ViewKey,string>>={products:'Thêm sản phẩm',categories:'Thêm danh mục',customers:'Thêm khách hàng',promotions:'Thêm mã ưu đãi',posts:'Thêm bài viết'};
  const tablePanel=(key:ViewKey)=> <section className="panel"><div className="table-toolbar"><label className="global-search"><Icon name="search"/><input value={tableSearch} onChange={e=>setTableSearch(e.target.value)} type="search" placeholder="Tìm trong danh sách..."/></label>{addLabel[key]&&<button className="button button-primary" onClick={()=>openForm(key as keyof typeof fieldDefs)}><Icon name="plus"/>{addLabel[key]}</button>}</div><div className="page-table-wrap"><table className="data-table"><thead><tr>{headers[key].map((head,i)=><th key={`${head}-${i}`}>{head}</th>)}</tr></thead><tbody>{renderGeneralRows()}</tbody></table></div></section>;

  const orderStats=[{label:'Tất cả đơn',filter:'',tone:'green',icon:'bag'},{label:'Chờ xác nhận',filter:'Chờ xác nhận',tone:'amber',icon:'clock'},{label:'Đang xử lý',filter:'Đang xử lý',tone:'orange',icon:'box'},{label:'Đang giao',filter:'Đang giao',tone:'blue',icon:'truck'},{label:'Đã giao',filter:'Đã giao',tone:'green',icon:'check'}];
  const ordersPage=()=>view==='orderCreate'?<OrderCreateWorkspace products={data.products} customers={data.customers} onBack={()=>go('orders')} onCreateCustomer={createPosCustomer} onCreateOrder={createPosOrder}/>:<div className="orders-page">
    <section className="orders-main">
      <div className="orders-heading"><div><h1>Đơn hàng</h1><p>Quản lý và theo dõi các đơn hàng của GEME.</p></div>
        <div className="orders-header-actions"><input className="order-filter" type="date" aria-label="Từ ngày" value={orderDateFrom} onChange={event=>setOrderDateFrom(event.target.value)}/><input className="order-filter" type="date" aria-label="Đến ngày" value={orderDateTo} onChange={event=>setOrderDateTo(event.target.value)}/><select className="order-filter" aria-label="Lọc trạng thái đơn hàng" value={statusFilter} onChange={event=>setStatusFilter(event.target.value)}><option value="">Trạng thái đơn hàng</option>{['Chờ xác nhận','Đang xử lý','Đang giao','Đã giao','Đã hủy'].map(status=><option key={status}>{status}</option>)}</select><select className="order-filter" aria-label="Lọc phương thức thanh toán" value={paymentFilter} onChange={event=>setPaymentFilter(event.target.value)}><option value="">Phương thức thanh toán</option>{Array.from(new Set(data.orders.map(order=>order.payment).filter(Boolean))).map(method=><option key={method} value={method}>{method}</option>)}</select><select className="order-filter" aria-label="Lọc vận chuyển" value={shippingFilter} onChange={event=>setShippingFilter(event.target.value)}><option value="">Vận chuyển</option>{Array.from(new Set(data.orders.map(order=>order.shipping).filter(Boolean))).map(method=><option key={method} value={method}>{method}</option>)}</select></div>
        <div className="orders-actions"><button className="button button-quiet" onClick={exportOrders}><Icon name="file"/>Xuất Excel</button><button className="button button-primary" onClick={()=>setView('orderCreate')}>＋ Tạo đơn hàng</button></div>
      </div>
      <div className="order-stats">{orderStats.map(stat=>{const count=stat.filter?data.orders.filter(order=>order.status===stat.filter).length:data.orders.length;return <button key={stat.label} className={'order-stat'+(statusFilter===stat.filter?' is-selected':'')} onClick={()=>setStatusFilter(stat.filter)}><span className={'stat-glyph '+stat.tone}><Icon name={stat.icon}/></span><span className="stat-copy"><small>{stat.label}</small><strong>{count}</strong></span></button>;})}</div>
      <section className="orders-table-panel"><div className="bulk-toolbar"><label className="check-label"><input type="checkbox" aria-label="Chọn tất cả đơn hàng" checked={orderRows.length>0&&orderRows.every(order=>selectedOrderRows.includes(order.id))} onChange={event=>setSelectedOrderRows(event.target.checked?orderRows.map(order=>order.id):[])}/><span>Chọn tất cả</span></label><select className="bulk-select" defaultValue="" disabled={!selectedOrderRows.length} aria-label="Cập nhật trạng thái hàng loạt" onChange={event=>{const nextStatus=event.target.value;if(nextStatus){selectedOrderRows.forEach(id=>changeOrder(id,nextStatus));setSelectedOrderRows([]);}}}><option value="">Xử lý hàng loạt</option><option>Đang xử lý</option><option>Đang giao</option><option>Đã giao</option><option>Đã hủy</option></select>{selectedOrderRows.length>0&&<span className="selected-count">Đã chọn {selectedOrderRows.length} đơn</span>}</div><div className="page-table-wrap order-table-scroll"><table className="data-table orders-full-table"><thead><tr><th className="check-column"></th><th>Mã đơn</th><th>Khách hàng</th><th>Sản phẩm</th><th>Tổng tiền</th><th>Thanh toán</th><th>Trạng thái</th><th>Thời gian</th><th></th></tr></thead><tbody>{orderRows.length?orderRows.map(order=><tr key={order.id} className={'orders-clickable-row'+(selectedOrderId===order.id?' row-selected':'')} tabIndex={0} aria-label={'Xem chi tiết đơn '+order.id} onClick={()=>setSelectedOrderId(order.id)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();setSelectedOrderId(order.id);}}}><td onClick={event=>event.stopPropagation()}><input type="checkbox" aria-label={"Chọn đơn "+order.id} checked={selectedOrderRows.includes(order.id)} onChange={event=>setSelectedOrderRows(current=>event.target.checked?[...current,order.id]:current.filter(id=>id!==order.id))}/></td><td><button className="order-id-button" type="button" onClick={event=>{event.stopPropagation();setSelectedOrderId(order.id);}}>#{order.id}</button></td><td><span className="order-customer">{order.customer||'Khách lẻ'}</span>{order.phone&&<small className="order-secondary">{order.phone}</small>}</td><td><span className="order-product">{order.items[0]?.image?<img className="product-thumb" src={order.items[0].image} alt=""/>:<span className="product-thumb" aria-hidden="true">◇</span>}<span>{order.product||'Đơn hàng'}<small className="order-secondary">{order.sku||'—'}{order.quantity>1?' · x'+order.quantity:''}</small></span></span></td><td className="amount">{money(order.total)}</td><td>{order.payment}</td><td><Pill>{order.status}</Pill></td><td>{order.date}<small className="order-secondary">{order.time}</small></td><td><button className="more-button" type="button" aria-label={'Chi tiết '+order.id} onClick={event=>{event.stopPropagation();setSelectedOrderId(order.id);}}>•••</button></td></tr>):<tr><td className="table-empty" colSpan={9}>Không có đơn hàng phù hợp.</td></tr>}</tbody></table></div><div className="orders-pagination"><span>Hiển thị {orderRows.length} / {data.orders.length} đơn hàng</span></div></section>
    </section>
    {selectedOrder?<OrderDetailPanel order={selectedOrder} onClose={()=>setSelectedOrderId('')} onConfirm={()=>changeOrder(selectedOrder.id,'Đang xử lý')} onShowBill={()=>setReceiptOrderId(selectedOrder.id)} onCustomerHistory={()=>setSearch(selectedOrder.phone||selectedOrder.customer)}/>:<aside className="order-drawer order-drawer-empty"><strong>Chi tiết đơn hàng</strong><p>Chọn một đơn hàng để xem thông tin khách, sản phẩm và thanh toán.</p></aside>}
  </div>;

  const dashboard=()=> <DashboardWorkspace products={data.products} orders={data.orders} promotions={data.promotions} posts={data.posts} customerCount={data.customers.length} report={dashboardReport} reportLoading={dashboardReportStatus==="loading"||apiStatus==="connecting"} onOpen={go} onSelectOrder={setSelectedOrderId}/>;
  const settings=()=> <div className="settings-grid"><section className="panel setting-card"><h2>Thông tin cửa hàng</h2><p>Thông tin liên hệ và nhận diện thương hiệu.</p><div className="field"><label>Tên cửa hàng</label><input value={siteSettings.storeName} onChange={event=>setSiteSettings(old=>({...old,storeName:event.target.value}))}/></div><div className="field"><label>Email hỗ trợ</label><input type="email" value={siteSettings.supportEmail} onChange={event=>setSiteSettings(old=>({...old,supportEmail:event.target.value}))} placeholder="Nhập email hỗ trợ"/></div><div className="field"><label>Số điện thoại</label><input type="tel" value={siteSettings.phone} onChange={event=>setSiteSettings(old=>({...old,phone:event.target.value}))} placeholder="Nhập số điện thoại"/></div><div className="field"><label>Địa chỉ</label><input value={siteSettings.address} onChange={event=>setSiteSettings(old=>({...old,address:event.target.value}))} placeholder="Nhập địa chỉ cửa hàng"/></div><div className="settings-actions"><button className="button button-primary" onClick={()=>void apiRequest('settings','PATCH',siteSettings).then(()=>notify('Đã lưu cài đặt vào database.')).catch(error=>notify(error instanceof Error?error.message:'Không thể lưu cài đặt.'))}>Lưu cài đặt</button></div></section><section className="panel setting-card"><h2>Kết nối backend</h2><p>Admin và storefront sử dụng chung API, mỗi ứng dụng chạy riêng.</p><div className="notice-card"><span className="activity-icon"> <Icon name="info"/></span><span>Trạng thái API<span><small>{apiStatus==='connected'?'Đã kết nối PostgreSQL qua API':apiStatus==='connecting'?'Đang kết nối API…':'API chưa kết nối; hãy kiểm tra backend và DATABASE_URL.'}</small></span></span></div><div className="notice-card"><span className="activity-icon amber"><Icon name="box"/></span><span>NestJS + PostgreSQL + Prisma<small>Danh mục, sản phẩm, đơn hàng, khách hàng, khuyến mãi và blog dùng chung database.</small></span></div><a className="button button-quiet" href="http://127.0.0.1:3000" target="_blank" rel="noreferrer">Mở storefront GEME</a></section><section className="panel setting-card pos365-setting-card"><div className="pos365-heading"><div><h2>Kết nối POS365</h2><p>Phiếu nhập kho, giá bán, tồn kho và đơn hàng được đồng bộ qua hàng đợi theo SKU/mã đơn. Thông tin đăng nhập chỉ lưu trong cấu hình backend.</p></div><span className={`pos365-badge ${pos365Result?.ok?'is-connected':pos365Result?.ok===false?'is-error':pos365Status?.syncEnabled?'is-connected':pos365Status?.configured?'is-ready':'is-unconfigured'}`}>{pos365Result?.ok?'Đã kết nối':pos365Result?.ok===false?'Cần kiểm tra':pos365Status?.syncEnabled?'Tự đồng bộ':'Chưa cấu hình'}</span></div><div className="notice-card"><span className={`activity-icon ${pos365Result?.ok?'':'amber'}`}><Icon name={pos365Result?.ok?'check':'info'}/></span><span>{pos365Result?.ok?'Kiểm tra kết nối thành công':pos365Result?.message?'Kết quả kiểm tra POS365':pos365Status?.configured?'Đã tìm thấy cấu hình POS365 phía máy chủ':'Chưa tìm thấy đủ cấu hình POS365'}<small>{pos365Result?.message||(!pos365Status?'Chưa đọc được trạng thái từ API GEME.':pos365Status.configured?'Có thể kiểm tra đăng nhập và quyền truy cập chi nhánh POS365.':'Cần host dạng https://{mã-cửa-hàng}.pos365.vn, tài khoản quản trị và mật khẩu.')}</small>{pos365Result?.branchName&&<small>Chi nhánh nhận phiếu: {pos365Result.branchName}.</small>}{pos365Result?.ok&&pos365Result.branchCount!==undefined&&<small>Số chi nhánh trong POS365: {pos365Result.branchCount}.</small>}</span></div><div className="notice-card"><span className={`activity-icon ${pos365Status?.syncEnabled?'':'amber'}`}><Icon name={pos365Status?.syncEnabled?'check':'box'}/></span><span>Trạng thái đồng bộ<span><small>Phiếu nhập chờ/lỗi: {pos365QueueSummary?.receipts.pending ?? '—'}/{pos365QueueSummary?.receipts.failed ?? '—'}; giá chờ/lỗi: {pos365QueueSummary?.prices.pending ?? '—'}/{pos365QueueSummary?.prices.failed ?? '—'}; tồn kho sản phẩm chờ/lỗi: {pos365QueueSummary?.stocks.pending ?? '—'}/{pos365QueueSummary?.stocks.failed ?? '—'}; đơn đang chờ: {pos365QueueSummary?.orders.pending ?? '—'}.</small><small>Đơn cần cấu hình thanh toán: {pos365QueueSummary?.orders.blocked ?? '—'}; đơn đã đồng bộ: {pos365QueueSummary?.orders.synced ?? '—'}.</small><small>Đơn chuyển khoản, MoMo hoặc thẻ đã thanh toán cần khai báo mã tài khoản POS365 tương ứng trên backend.</small></span></span></div><div className="pos365-actions"><span className="muted">Phiếu nhập, giá và đơn mới tự đồng bộ. Nút tồn hiện tại tạo phiếu kiểm kê một lần.</span><button className="button button-quiet" type="button" onClick={()=>void syncCurrentInventory()} disabled={!pos365Status?.syncEnabled||pos365StockSyncing}>{pos365StockSyncing?'Đang đồng bộ tồn…':'Đồng bộ tồn hiện tại'}</button><button className="button button-quiet" type="button" onClick={()=>void syncUnsentOrders().then(result=>{notify(`Đã đưa ${result.queued||0} đơn chưa đồng bộ vào hàng đợi POS365.`);return fetch(`${apiBase}/integrations/pos365/sync-summary`,{cache:'no-store'});}).then(response=>response?.json()).then(summary=>{if(summary)setPos365QueueSummary(summary as Pos365QueueSummary);}).catch(error=>notify(error instanceof Error?error.message:'Không thể đưa đơn vào hàng đợi POS365.'))} disabled={!pos365Status?.syncEnabled}>Đồng bộ đơn cũ</button><button className="button button-primary" type="button" onClick={()=>void testPos365Connection()} disabled={pos365Checking||apiStatus!=='connected'}>{pos365Checking?'Đang kiểm tra…':'Kiểm tra kết nối'}</button></div></section></div>;


  return <div className="app-shell"><aside className={`sidebar ${menuOpen?'open':''}`}><a className="brand" href="#tong-quan" onClick={()=>go('overview')}><span className="brand-word">G E M E</span><span className="brand-caption">SILVER &amp; GEMSTONE JEWELRY</span></a><nav className="side-nav" aria-label="Điều hướng quản trị">{menu.map((item) => {
  const active = view === item.key || (item.key === 'orders' && view === 'orderCreate') || (item.key === 'products' && (view === 'productCreate' || view === 'categories' || view === 'materials' || view === 'pricing')) || (item.key === 'promotions' && view === 'promotionCreate') || (item.key === 'reports' && view === 'revenue') || (item.key === 'inventory' && (view === 'inventoryInbound' || view === 'inventoryOutbound' || view === 'inventoryHistory' || view === 'inventoryReceipts'));
  const toggleSubmenu = () => setExpandedMenus((current) => ({ ...current, [item.key]: !current[item.key] }));
  const openSubmenu = () => setExpandedMenus((current) => ({ ...current, [item.key]: true }));
  return <div className="nav-group" key={item.key}>
    {item.chevron ? <div className={`nav-item nav-item-split ${active ? 'active' : ''}`}>
      <span className="nav-icon"><Icon name={item.icon}/></span>
      <button type="button" className="nav-main-link" onClick={() => { go(item.key); openSubmenu(); }}>{item.label}</button>
      {item.badge && <b className="nav-badge">{item.badge}</b>}
      <button type="button" className="nav-chevron nav-chevron-action" aria-label={expandedMenus[item.key] ? `Thu gọn menu ${item.label}` : `Mở menu ${item.label}`} title="Hiện menu con" aria-expanded={!!expandedMenus[item.key]} onClick={toggleSubmenu}><Icon name="chevron"/></button>
    </div> : <button className={`nav-item ${active ? 'active' : ''}`} onClick={() => go(item.key)}><span className="nav-icon"><Icon name={item.icon}/></span><span>{item.label}</span>{item.badge && <b className="nav-badge">{item.badge}</b>}</button>}
    {item.key === 'orders' && expandedMenus.orders === true && <div className="nav-submenu"><button className={view === 'orderCreate' ? 'active' : ''} onClick={() => go('orderCreate')}>Tạo đơn hàng</button></div>}
    {item.key === 'products' && expandedMenus.products === true && <div className="nav-submenu"><button className={view === 'products' ? 'active' : ''} onClick={() => go('products')}>Tất cả sản phẩm</button><button className={view === 'productCreate' ? 'active' : ''} onClick={openProductCreate}>Thêm sản phẩm</button><button className={view === 'pricing' ? 'active' : ''} onClick={() => go('pricing')}>Hồ sơ giá</button><button className={view === 'categories' ? 'active' : ''} onClick={() => go('categories')}>Danh mục</button><button className={view === 'materials' ? 'active' : ''} onClick={() => go('materials')}>Loại đá</button></div>}
    {item.key === 'promotions' && expandedMenus.promotions === true && <div className="nav-submenu"><button className={view === 'promotions' ? 'active' : ''} onClick={() => go('promotions')}>Tất cả khuyến mãi</button><button className={view === 'promotionCreate' ? 'active' : ''} onClick={() => go('promotionCreate')}>Tạo khuyến mãi</button></div>}
    {item.key === 'posts' && expandedMenus.posts === true && <div className="nav-submenu"><button className={view === 'posts' ? 'active' : ''} onClick={() => go('posts')}>Tất cả bài viết</button></div>}
    {item.key === 'inventory' && expandedMenus.inventory === true && <div className="nav-submenu"><button className={view === 'inventory' ? 'active' : ''} onClick={() => go('inventory')}>Tồn kho sản phẩm</button><button className={view === 'inventoryInbound' ? 'active' : ''} onClick={() => go('inventoryInbound')}>Nhập hàng</button><button className={view === 'inventoryOutbound' ? 'active' : ''} onClick={() => go('inventoryOutbound')}>Xuất kho</button><button className={view === 'inventoryReceipts' ? 'active' : ''} onClick={() => go('inventoryReceipts')}>Phiếu nhập</button><button className={view === 'inventoryHistory' ? 'active' : ''} onClick={() => go('inventoryHistory')}>Lịch sử tồn kho</button></div>}
    {item.key === 'reports' && expandedMenus.reports === true && <div className="nav-submenu"><button className={view === 'reports' ? 'active' : ''} onClick={() => go('reports')}>Tổng quan báo cáo</button><button className={view === 'revenue' ? 'active' : ''} onClick={() => go('revenue')}>Doanh thu</button><button onClick={() => { if (view !== 'reports') go('reports'); window.setTimeout(() => document.getElementById('report-best-sellers')?.scrollIntoView({ behavior: 'smooth' }), 0); }}>Sản phẩm bán chạy</button><button onClick={() => { if (view !== 'reports') go('reports'); window.setTimeout(() => document.getElementById('report-customers')?.scrollIntoView({ behavior: 'smooth' }), 0); }}>Khách hàng</button><button onClick={() => { if (view !== 'reports') go('reports'); window.setTimeout(() => document.getElementById('report-orders')?.scrollIntoView({ behavior: 'smooth' }), 0); }}>Đơn hàng</button><button onClick={() => { if (view !== 'reports') go('reports'); window.setTimeout(() => document.getElementById('report-promotions')?.scrollIntoView({ behavior: 'smooth' }), 0); }}>Hiệu quả khuyến mãi</button></div>}
  </div>;
})}</nav><div className="sidebar-bottom"><div className="service-status"><i/> <span>Website đang hoạt động</span></div><a href="http://127.0.0.1:3000" target="_blank" rel="noreferrer">Xem website <Icon name="arrow"/></a></div></aside><main className="workspace"><header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setMenuOpen(v=>!v)} aria-label="Mở menu"><Icon name="menu"/></button><label className="global-search"><Icon name="search"/><input value={search} onChange={e=>setSearch(e.target.value)} type="search" placeholder={view==='orders'?'Tìm kiếm mã đơn, khách hàng...':view==='products'?'Tìm kiếm sản phẩm, mã SKU, danh mục...':'Tìm kiếm sản phẩm, đơn hàng, khách hàng...'}/></label><div className="topbar-actions"><button className="icon-button notification-button" onClick={()=>notify('Chưa có thông báo mới.')} aria-label="Thông báo"><Icon name="bell"/></button><button className="admin-profile" onClick={()=>notify('Giao diện quản trị GEME.')}><span className="avatar"><Icon name="person"/></span><strong>Admin</strong><Icon name="chevron"/></button></div></header><div className="page-content">{apiStatus==='offline'&&view!=='banners'&&view!=='orders'&&view!=='products'&&view!=='productCreate'&&view!=='categories'&&view!=='materials'&&view!=='customers'&&view!=='promotions'&&view!=='promotionCreate'&&view!=='posts'&&view!=='blogEditor'&&view!=='reports'&&view!=='revenue'&&view!=='inventory'&&view!=='inventoryInbound'&&view!=='inventoryOutbound'&&view!=='inventoryHistory'&&view!=='inventoryReceipts'&&<div className="demo-notice"><Icon name="info"/>Chưa kết nối dữ liệu backend. Các danh sách sẽ hiển thị khi có dữ liệu.</div>}{view==='banners'?<BannerFooterWorkspace onNotify={notify}/>:(view==='orders'||view==='orderCreate')?ordersPage():view==='pricing'?<PriceProfileWorkspace products={data.products} onSave={persistProduct} onNotify={notify} onSyncAll={syncAllPrices} onRefresh={reloadProducts}/>:view==='productCreate'?<ProductCreatePage products={data.products} categories={data.categories} materials={data.materials} initialCategory={productCategoryPreset} onBack={backFromProductCreate} onNotify={notify} onSave={async(created,publish)=>{const saved=await persistProduct(created,publish);setProductCategoryPreset(undefined);setView('products');setMenuOpen(false);notify(publish?`Đã đăng ${saved.id} với ${saved.gallery?.length??0} ảnh.`:`Đã lưu nháp ${saved.id} với ${saved.gallery?.length??0} ảnh.`);}}/>:view==='materials'?<MaterialsWorkspace materials={data.materials} onChange={(materials)=>setData(old=>({...old,materials}))} onPersist={persistMaterial} syncStatus={catalogSyncStatus} onNotify={notify}/>:view==='categories'?<CategoriesWorkspace categories={data.categories} onSave={(categories)=>persistCollection('categories',data.categories,categories) as Promise<AdminCategory[]>} onDelete={deleteCategory} onNotify={notify} onCreateProduct={requestProductCreate}/>:view==='promotionCreate'?<PromotionCreateWorkspace products={data.products} categories={data.categories} existingCodes={data.promotions.map((promotion)=>String(promotion.code||''))} onBack={()=>go('promotions')} onSave={async(promotion)=>{const saved=await apiRequest('promotions','POST',toApiPromotion(promotion)) as Row;const mapped=fromApiPromotion(saved);setData(old=>({...old,promotions:[mapped,...old.promotions]}));setView('promotions');setMenuOpen(false);window.scrollTo({top:0,behavior:'smooth'});notify('Đã lưu khuyến mãi vào database.');}}/>:view==='revenue'?<RevenueWorkspace report={dashboardReport} loading={dashboardReportStatus==="loading"}/>:view==='reports'?<ReportsWorkspace report={dashboardReport} loading={dashboardReportStatus==="loading"}/>:view==='blogEditor'?<BlogEditorPage post={blogPostDraft} categories={blogCategories} onBack={()=>go('posts')} onSave={saveBlogPost} onSaveCategory={saveBlogCategory} onNotify={notify}/>:view==='posts'?<BlogWorkspace posts={data.posts} categories={blogCategories} onCreate={()=>openBlogEditor()} onEdit={(post)=>openBlogEditor(post)} onDelete={async(post)=>{if(!post.apiId)throw new Error('Không tìm thấy mã bài viết trong API.');await apiRequest(`blog/${encodeURIComponent(String(post.apiId))}`,'DELETE');setData(old=>({...old,posts:old.posts.filter((item)=>item.apiId!==post.apiId)}));notify('Đã xóa bài viết khỏi database.');}} onNotify={notify}/>:view==='promotions'?<PromotionsWorkspace promotions={data.promotions} onChange={(promotions)=>setData(old=>({...old,promotions}))} onCreate={()=>go('promotionCreate')} onPersist={async(promotion)=>{const id=promotion.apiId?encodeURIComponent(String(promotion.apiId)):'';const saved=await apiRequest(id?'promotions/'+id:'promotions',id?'PATCH':'POST',toApiPromotion(promotion)) as Row;const mapped=fromApiPromotion(saved) as typeof promotion;setData(old=>({...old,promotions:id?old.promotions.map(item=>item.apiId===mapped.apiId?mapped:item):[mapped,...old.promotions]}));return mapped;}} onNotify={notify}/>:view==='inventory'||view==='inventoryInbound'||view==='inventoryOutbound'||view==='inventoryHistory'||view==='inventoryReceipts'?<InventoryWorkspace categories={data.categories} materials={data.materials} initialTab={view==='inventoryInbound'?'inbound':view==='inventoryOutbound'?'outbound':view==='inventoryHistory'?'history':view==='inventoryReceipts'?'receipts':'stock'} onNavigate={(tab:InventoryTab)=>go(tab==='inbound'?'inventoryInbound':tab==='outbound'?'inventoryOutbound':tab==='history'?'inventoryHistory':tab==='receipts'?'inventoryReceipts':'inventory')} onNotify={notify} onCategoryCreated={(category)=>setData(old=>({...old,categories:old.categories.some((item)=>item.id===category.id)?old.categories.map((item)=>item.id===category.id?category:item):[...old.categories,category]}))}/>:<>{view!=='products'&&<PageTitle view={view}>{(view==='overview')&&<button className="date-control" onClick={()=>notify('Bộ lọc ngày sẽ sử dụng API khi backend được kết nối.')}><Icon name="calendar"/><span>Chọn khoảng thời gian</span><Icon name="chevron"/></button>}</PageTitle>}{view==='overview'?dashboard():view==='settings'?settings():view==='customers'?<CustomersWorkspace customers={data.customers} onAdd={()=>openForm('customers')} onNotify={notify}/>:view==='products'?<ProductsWorkspace products={data.products} categories={data.categories} materials={data.materials} onAdd={openProductCreate} onSave={persistProduct} onDelete={deleteProduct} onNotify={notify}/>:tablePanel(view)}</>}</div></main>{toast&&<div className="toast show" role="status">{toast}</div>}{formView&&<div className="dialog-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)closeForm();}}><section className="edit-dialog" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><div className="dialog-heading"><div><span className="eyebrow">GEME ADMIN</span><h2 id="dialogTitle">{editing?'Sửa':'Thêm'} {viewMeta[formView].title.toLocaleLowerCase('vi')}</h2></div><button className="icon-button dialog-close" onClick={closeForm} aria-label="Đóng"><Icon name="close"/></button></div><form onSubmit={saveForm}><div className="dialog-fields">{fieldDefs[formView].map(field=><div className="field" key={field.key}><label htmlFor={`admin-${field.key}`}>{field.label}</label><input id={`admin-${field.key}`} name={field.key} type={field.type|| (field.numeric?'number':'text')} min={field.numeric?0:undefined} value={draft[field.key]||''} readOnly={field.key==='id'&&!!editing} onChange={e=>setDraft(old=>({...old,[field.key]:e.target.value}))} required/></div>)}</div><div className="dialog-actions"><button type="button" className="button button-quiet" onClick={closeForm}>Hủy</button><button className="button button-primary" type="submit">Lưu thông tin</button></div></form></section></div>}{selectedReceiptOrder && <OrderReceiptModal order={selectedReceiptOrder} onClose={()=>setReceiptOrderId("")}/>}</div>;
}
function Activity({icon,tone,children}:{icon:string;tone?:string;children:React.ReactNode}){return <div className="activity-item"><span className={`activity-icon ${tone||''}`}><Icon name={icon}/></span><span className="activity-text">{children}</span></div>;}


